SELECT COUNT(DISTINCT UserId) 
    FROM badges 
    WHERE Name = 'Supporter' AND Date >= '2011-01-01' AND Date < '2012-01-01';

SELECT OwnerDisplayName 
    FROM posts 
    WHERE ViewCount = (SELECT MAX(ViewCount) FROM posts) AND OwnerDisplayName <> '';

SELECT lat, lng 
    FROM circuits 
    WHERE circuitId = (SELECT circuitId FROM races WHERE name = 'Abu Dhabi Grand Prix');

SELECT COUNT(driverId) AS number_of_finished_drivers
    FROM results
    WHERE raceId = (SELECT raceId FROM races WHERE date = '2015-11-29') AND statusId = 1;

SELECT DISTINCT team_fifa_api_id 
    FROM Team_Attributes 
    WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT potential FROM Player_Attributes PA 
        JOIN Player P ON PA.player_api_id = P.player_api_id 
        WHERE P.player_name = 'Aaron Doran';

